      // Allign the global matrix to the block matrix
      a_block[ty][tx] = d_a[row * width + (i * BLOCK_SIZE + tx)];
      b_block[ty][tx] = d_b[(i * BLOCK_SIZE + ty) * width + col];

      // Make sure all the threads are synchronized
      ....

      // Multiply the block matrix
